  'view_campaign_details': 'অভিযানের বিবরণ দেখুন',
  'vmovexa_dooh_engine': 'VMOVEXA DOOH ইঞ্জিন',
  'advertiser_faq1_a': 'অভিযানে যান এবং "অভিযান তৈরি করুন" এ ট্যাপ করুন। প্রাথমিক তথ্য লিখতে, আপনার ১৬:৯ ক্রিয়েটিভ সামগ্রী আপলোড করতে, লক্ষ্য ট্রানজিট ফ্লিট নির্বাচন করতে, সময়সূচী ও বাজেট কনফিগার করতে এবং যাচাইয়ের জন্য জমা দিতে ধাপে ধাপে নির্দেশাবলী অনুসরণ করুন।',
  'advertiser_faq1_q': 'কীভাবে একটি ট্রানজিট বিজ্ঞাপন অভিযান তৈরি এবং চালু করবেন?',
  'advertiser_faq2_a': 'আমরা MP4 (H.264), JPG, PNG এবং HTML5 জিপ প্যাকেজ সমর্থন করি। স্ট্যান্ডার্ড রেজোলিউশন ১৯২০×১০৮০ (১৬:৯ আকৃতির অনুপাত), ভিডিও বিজ্ঞাপনের সর্বোচ্চ সময়কাল ৩০ সেকেন্ড এবং ফাইলের আকার ৫০ মেগাবাইটের নিচে হতে হবে।',
  'advertiser_faq2_q': 'সুপারিশকৃত ক্রিয়েটিভ স্পেসিফিকেশন কী কী?',
  'advertiser_faq3_a': 'প্রতিটি অভিযান একটি ট্র্যাকযোগ্য QR পরিচয় তৈরি করে। যাত্রীরা যখন স্ক্রিনে প্রদর্শিত QR কোডটি স্ক্যান করেন, তখন সিস্টেম সময়, অবস্থান, গাড়ির আইডি রেকর্ড করে এবং তাদের আপনার ল্যান্ডিং পৃষ্ঠায় পুনঃনির্দেশিত করে।',
  'advertiser_faq3_q': 'স্মার্ট QR কোড লিড অ্যাট্রিবিউশন কীভাবে কাজ করে?',
  'advertiser_faq4_a': 'অভিযানগুলির জন্য দৈনিক বা মোট বাজেট মডেলে চার্জ করা হয়। বিজ্ঞাপন ব্যয়ের উপর GST (১৮%) গণনা করা হয়। যাচাইকরণের অনুমোদনের পর ট্যাক্স ক্রেডিট সহ ইনভয়েস স্বয়ংক্রিয়ভাবে তৈরি হয়।',
  'advertiser_faq4_q': 'বিলিং, GST ইনভয়েস এবং কর্তন কীভাবে কাজ করে?',
